"""Extract HIES (Household Income and Expenditure Survey of Iran) questionnaires from the PDF forms."""

from __future__ import annotations

import argparse
import csv
from pathlib import Path

__all__ = ["extract", "extract_year", "main", "write_csv"]

# --- where things live --------------------------------------------------------
# data/     external inputs, not in git (PDFs, household occurrence tables)
# curated/  hand-kept decisions: the only files anyone edits; curated/<stage>/
#           holds the decisions applied to output/<stage>/
# output/   generated by `hiesir-codebook build`, tracked, never edited
# reports/  generated review aids, not in git
DATA_DIR = Path("data")
CURATED = Path("curated")
OUTPUT = Path("output")
REPORTS = Path("reports")
EXTRACTED = OUTPUT / "1_extracted"  # PDFs -> CSV, as printed
CORRECTED = OUTPUT / "2_corrected"  # + curated/2_corrected/
ITEMS = OUTPUT / "3_items"  # chains, links and relations across years (+ curated/3_items/)
GROUPS = OUTPUT / "4_groups"  # group headers across years (+ curated/4_groups/)
CURATED_CORRECTED = CURATED / "2_corrected"  # corrections.csv, spelling.csv
CURATED_ITEMS = CURATED / "3_items"  # links.csv, relations.csv
CURATED_GROUPS = CURATED / "4_groups"  # links.csv

from .parse import Row, extract, extract_year  # noqa: E402  (after the paths it may use)

# years whose PDF has a usable text layer (1363-1381 are scans; the 1401 PDF
# is a data dictionary, not the questionnaire)
SUPPORTED_YEARS = [1382, *range(1383, 1401), 1402, 1403]

CSV_COLUMNS = [
    "section",
    "kind",
    "level",
    "code",
    "sub",
    "expenditure_code",
    "description",
    "page",
    "top",
    "bottom",
    "left",
    "right",
]


def write_csv(rows: list[Row], path: Path) -> None:
    """One row per section / group header / item, in questionnaire order.

    The section rows carry the full PDF title in ``description``; ``page``
    is the 1-based PDF page.  UTF-8 with BOM so Excel shows Persian text.
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8-sig", newline="") as f:
        w = csv.writer(f, lineterminator="\n")  # LF: tracked data diffs cleanly on every OS
        w.writerow(CSV_COLUMNS)
        for r in rows:
            w.writerow(
                [
                    r.section,
                    r.kind,
                    r.level or "",
                    r.code,
                    r.sub or "",
                    r.expenditure_code or "",
                    r.desc,
                    r.page + 1,
                    "" if r.top is None else f"{r.top:.1f}",
                    "" if r.bottom is None else f"{r.bottom:.1f}",
                    "" if r.left is None else f"{r.left:.1f}",
                    "" if r.right is None else f"{r.right:.1f}",
                ]
            )


def build(year: int, data: Path = DATA_DIR, csv_dir: Path = EXTRACTED) -> Path:
    """Extract one year's questionnaire and write ``<csv_dir>/questionnaire_<year>.csv``."""
    rows = extract_year(year, data)
    out = csv_dir / f"questionnaire_{year}.csv"
    write_csv(rows, out)
    return out


def build_all(data: Path = DATA_DIR, extract_pdfs: bool = True) -> None:
    """Regenerate every stage of output/ in order.

    extract (PDFs -> 1_extracted, skipped when the PDFs are not available)
    -> correct (+ curated/2_corrected -> 2_corrected) -> chains and relations
    (-> 3_items) -> the groups (-> 4_groups) -> the explorer page.
    """
    from . import chains, correct, explorer, groups, relations

    if extract_pdfs and (data / "pdf").is_dir():
        for y in SUPPORTED_YEARS:
            build(y, data, EXTRACTED)
        print(f"extracted {len(SUPPORTED_YEARS)} years -> {EXTRACTED}")
    elif extract_pdfs:
        print(f"no {data / 'pdf'}: keeping {EXTRACTED} as it is")
    else:
        print(f"keeping {EXTRACTED} as it is")
    correct.main([])
    chains.main([])
    relations.main([])
    groups.main([])
    explorer.main([])


def main(argv: list[str] | None = None) -> None:
    ap = argparse.ArgumentParser(
        prog="hiesir-codebook",
        description=__doc__,
        epilog="'hiesir-codebook build' regenerates every stage of output/.",
    )
    ap.add_argument("years", nargs="+", help="survey years (e.g. 1382 1403), 'all', or 'build'")
    ap.add_argument("--data", type=Path, default=DATA_DIR, help="folder with pdf/ (default: data/)")
    ap.add_argument(
        "--csv-dir",
        type=Path,
        default=EXTRACTED,
        help=f"where to write the CSV extracts (default: {EXTRACTED.as_posix()}/)",
    )
    ap.add_argument("--no-extract", action="store_true", help="build: keep 1_extracted, do not read PDFs")
    args = ap.parse_args(argv)
    if args.years == ["build"]:
        build_all(args.data, extract_pdfs=not args.no_extract)
        return
    years = SUPPORTED_YEARS if args.years == ["all"] else [int(y) for y in args.years]
    for y in years:
        print(build(y, args.data, args.csv_dir), flush=True)
